    { id:"p3h-717", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken amerikansk delstat är uppkallad efter den engelska \"jungfrudrottningen\"?", answer: "Virginia", accept: ["virginia"], explanation: "Namnet gavs av Walter Raleigh 1584.", sources: ["sv:Virginia"] },
    { id:"p3h-718", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken skådespelerska spelade jungfrudrottningen i filmen \"Elizabeth\" från 1998?", answer: "Cate Blanchett", accept: ["cate blanchett","blanchett"], explanation: "Hon spelade rollen igen 2007.", sources: ["sv:Elizabeth (film)"] },
    { id:"p3h-720", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "I vilket landskap gjorde Nils Dacke uppror mot Gustav Vasa?", answer: "Småland", accept: ["småland"], explanation: "Upproret kallas Dackefejden.", sources: ["sv:Dackefejden"] },
    { id:"p3h-721", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken roman av Vilhelm Moberg från 1941 är inspirerad av Dackefejden?", answer: "Rid i natt!", accept: ["rid i natt!","rid i natt"], explanation: "Romanen var en protest mot nazismen.", sources: ["sv:Rid i natt!"] },
    { id:"p3h-722", category: "historia", difficulty: "svår", tags: ["p3-historia"], question: "Vilket år började Dackefejden?", answer: "1542", accept: ["1542"], explanation: "Dacke dödades året efter i Blekinge.", sources: ["sv:Dackefejden"] },
    { id:"p3h-723", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken engelsman räddade Pocahontas enligt legenden?", answer: "John Smith", accept: ["john smith","smith"], explanation: "Historien är omstridd bland historiker.", sources: ["sv:Pocahontas"] },
    { id:"p3h-724", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken engelsman gifte sig Pocahontas med?", answer: "John Rolfe", accept: ["john rolfe","rolfe"], explanation: "Hon döptes och tog namnet Rebecca.", sources: ["sv:Pocahontas"] },
    { id:"p3h-725", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "I vilket land dog Pocahontas 1617?", answer: "England", accept: ["england"], explanation: "Hon dog i Gravesend vid Themsen.", sources: ["sv:Pocahontas"] },
    { id:"p3h-726", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "I vilken stad valdes Gustav Vasa till kung den 6 juni 1523?", answer: "Strängnäs", accept: ["strängnäs"], explanation: "Dagen är Sveriges nationaldag.", sources: ["sv:Gustav Vasa"] },
    { id:"p3h-727", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken riksdag 1527 inledde reformationen i Sverige?", answer: "Västerås riksdag", accept: ["västerås riksdag","västerås"], explanation: "Kyrkans egendomar drogs in till kronan.", sources: ["sv:Västerås riksdag 1527"] },
    { id:"p3h-728", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken hansestad gav Gustav Vasa stöd i befrielsekriget?", answer: "Lübeck", accept: ["lübeck"], explanation: "Skulderna till Lübeck tyngde hans regering.", sources: ["sv:Gustav Vasa"] },
    { id:"p3h-729", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vad hette motståndsgruppen som Sophie Scholl tillhörde?", answer: "Vita rosen", accept: ["vita rosen","die weiße rose"], explanation: "Gruppen delade ut flygblad mot nazismen.", sources: ["sv:Vita rosen"] },
    { id:"p3h-730", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "I vilken stad greps Sophie Scholl 1943?", answer: "München", accept: ["münchen"], explanation: "Hon greps när hon delade ut flygblad på universitetet.", sources: ["sv:Sophie Scholl"] },
    { id:"p3h-731", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vad hette Sophie Scholls bror, som avrättades samma dag?", answer: "Hans Scholl", accept: ["hans scholl","hans"], explanation: "De avrättades i februari 1943.", sources: ["sv:Hans Scholl"] },
    { id:"p3h-732", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Hur avrättades Sophie Scholl?", answer: "Med giljotin", accept: ["med giljotin","giljotin","giljotinen"], explanation: "Hon var 21 år gammal.", sources: ["sv:Sophie Scholl"] },
    { id:"p3h-733", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilket år avrättades 71 personer för trolldom på en enda dag i Torsåker?", answer: "1675", accept: ["1675"], explanation: "Det är den största avrättningen i Sverige i fredstid.", sources: ["sv:Häxprocessen i Torsåker"] },
    { id:"p3h-734", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "I vilket landskap ligger Torsåker, platsen för Sveriges största häxavrättning?", answer: "Ångermanland", accept: ["ångermanland"], explanation: "Platsen kallas Bålberget.", sources: ["sv:Häxprocessen i Torsåker"] },
    { id:"p3h-735", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vad kallas häxhysterin i Sverige 1668–1676?", answer: "Det stora oväsendet", accept: ["det stora oväsendet","stora oväsendet"], explanation: "Omkring 300 personer avrättades.", sources: ["sv:Det stora oväsendet"] },
    { id:"p3h-736", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilket sjöslag 1790, det största i Östersjöns historia, vann Gustav III mot ryssarna?", answer: "Andra slaget vid Svensksund", accept: ["andra slaget vid svensksund","svensksund"], explanation: "Slaget stod i Finska viken.", sources: ["sv:Andra slaget vid Svensksund"] },
    { id:"p3h-737", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vad kallas den stilepok inom konst och inredning som är uppkallad efter Gustav III?", answer: "Gustaviansk stil", accept: ["gustaviansk stil","gustavianskt","gustaviansk"], explanation: "Stilen var inspirerad av antiken och fransk nyklassicism.", sources: ["sv:Gustaviansk stil"] },
    { id:"p3h-738", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilket smeknamn har Jeanne d'Arc?", answer: "Jungfrun av Orléans", accept: ["jungfrun av orléans","jungfrun från orléans"], explanation: "Hon hävde belägringen av Orléans 1429.", sources: ["sv:Jeanne d'Arc"] },
    { id:"p3h-739", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "I vilken stad brändes Jeanne d'Arc på bål 1431?", answer: "Rouen", accept: ["rouen"], explanation: "Hon var omkring 19 år gammal.", sources: ["sv:Jeanne d'Arc"] },
    { id:"p3h-740", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "I vilket krig mellan England och Frankrike stred Jeanne d'Arc?", answer: "Hundraårskriget", accept: ["hundraårskriget"], explanation: "Kriget pågick 1337–1453.", sources: ["sv:Hundraårskriget"] },
    { id:"p3h-741", category: "historia", difficulty: "svår", tags: ["p3-historia"], question: "Vilket år helgonförklarades Jeanne d'Arc?", answer: "1920", accept: ["1920"], explanation: "Hon är ett av Frankrikes skyddshelgon.", sources: ["sv:Jeanne d'Arc"] },
    { id:"p3h-742", category: "historia", difficulty: "lätt", tags: ["p3-historia"], question: "Hur många hustrur hade Henrik VIII?", answer: "Sex", accept: ["sex","6"], explanation: "Två av dem halshöggs.", sources: ["sv:Henrik VIII av England"] },
    { id:"p3h-743", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken kyrka grundade Henrik VIII när han bröt med påven 1534?", answer: "Engelska kyrkan", accept: ["engelska kyrkan","church of england","anglikanska kyrkan"], explanation: "Påven vägrade ogiltigförklara hans första äktenskap.", sources: ["sv:Engelska kyrkan"] },
    { id:"p3h-744", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken engelsk folkvisa påstås ofta, troligen felaktigt, ha skrivits av Henrik VIII?", answer: "Greensleeves", accept: ["greensleeves"], explanation: "Melodin är sannolikt från tiden efter hans död.", sources: ["sv:Greensleeves"] },
    { id:"p3h-745", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilket av Henrik VIII:s krigsskepp sjönk 1545 och bärgades 1982?", answer: "Mary Rose", accept: ["mary rose"], explanation: "Skeppet visas i Portsmouth.", sources: ["sv:Mary Rose"] },
    { id:"p3h-746", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "På vilket torg i Stockholm avrättades många i Stockholms blodbad 1520?", answer: "Stortorget", accept: ["stortorget"], explanation: "Avrättningarna skedde i november 1520.", sources: ["sv:Stockholms blodbad"] },
    { id:"p3h-747", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken änka ledde försvaret av Stockholm mot Kristian II 1520?", answer: "Kristina Gyllenstierna", accept: ["kristina gyllenstierna","gyllenstierna"], explanation: "Hon var änka efter riksföreståndaren Sten Sture d.y.", sources: ["sv:Kristina Gyllenstierna"] },
    { id:"p3h-748", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken blivande kungs far avrättades i Stockholms blodbad?", answer: "Gustav Vasas", accept: ["gustav vasas","gustav vasa"], explanation: "Fadern hette Erik Johansson.", sources: ["sv:Stockholms blodbad"] },
    { id:"p3h-749", category: "historia", difficulty: "svår", tags: ["p3-historia"], question: "Ungefär hur många personer avrättades i Stockholms blodbad?", answer: "Omkring 80–100", accept: ["omkring 80–100","80","100","ett hundratal"], explanation: "De flesta var adelsmän och borgare.", sources: ["sv:Stockholms blodbad"] },
    { id:"p3h-750", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilket djur sägs Kleopatra ha låtit bita sig för att ta sitt liv?", answer: "En orm", accept: ["en orm","orm","asp","kobra","egyptisk kobra"], explanation: "Hon dog år 30 f.Kr.", sources: ["sv:Kleopatra VII"] },
    { id:"p3h-751", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken skådespelerska spelade Kleopatra i den påkostade filmen från 1963?", answer: "Elizabeth Taylor", accept: ["elizabeth taylor","taylor"], explanation: "Richard Burton spelade Marcus Antonius.", sources: ["sv:Cleopatra (film 1963)"] },
    { id:"p3h-752", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken makedonisk-grekisk dynasti tillhörde Kleopatra?", answer: "Ptolemaierna", accept: ["ptolemaierna","ptolemeiska dynastin","ptolemaios"], explanation: "Hon var den sista härskaren av dynastin.", sources: ["sv:Ptolemaiska dynastin"] },
    { id:"p3h-753", category: "historia", difficulty: "svår", tags: ["p3-historia"], question: "Vad hette Kleopatras son med Julius Caesar?", answer: "Caesarion", accept: ["caesarion","ptolemaios xv"], explanation: "Han dödades på Octavianus order.", sources: ["sv:Caesarion"] },
    { id:"p3h-754", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vad hette Clyde i Bonnie och Clyde i efternamn?", answer: "Barrow", accept: ["barrow"], explanation: "Gänget kallades Barrow Gang.", sources: ["sv:Bonnie och Clyde"] },
    { id:"p3h-755", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilket år dödades Bonnie och Clyde i ett bakhåll?", answer: "1934", accept: ["1934"], explanation: "De sköts i Louisiana i maj 1934.", sources: ["sv:Bonnie och Clyde"] },
    { id:"p3h-756", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilka skådespelare spelade Bonnie och Clyde i filmen från 1967?", answer: "Faye Dunaway och Warren Beatty", accept: ["faye dunaway och warren beatty","faye dunaway","warren beatty"], explanation: "Filmen räknas som starten på New Hollywood.", sources: ["sv:Bonnie och Clyde (film)"] },
    { id:"p3h-757", category: "historia", difficulty: "svår", tags: ["p3-historia"], question: "Vad hette Bonnie i Bonnie och Clyde i efternamn?", answer: "Parker", accept: ["parker"], explanation: "Hon skrev dikter om deras liv på flykt.", sources: ["sv:Bonnie och Clyde"] },
    { id:"p3h-758", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Från vilket land kom Marie Antoinette?", answer: "Österrike", accept: ["österrike"], explanation: "Hon var dotter till kejsarinnan Maria Teresia.", sources: ["sv:Marie-Antoinette"] },
    { id:"p3h-759", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vad sägs Marie Antoinette ha sagt när hon fick höra att folket saknade bröd?", answer: "\"Låt dem äta kakor\"", accept: ["\"låt dem äta kakor\"","låt dem äta kaka","låt dem äta bakelser","qu'ils mangent de la brioche"], explanation: "Citatet är troligen felaktigt tillskrivet henne.", sources: ["sv:Marie-Antoinette"] },
    { id:"p3h-760", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilket år avrättades Marie Antoinette?", answer: "1793", accept: ["1793"], explanation: "Hon giljotinerades i oktober 1793.", sources: ["sv:Marie-Antoinette"] },
    { id:"p3h-761", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vad kallas skandalen 1785 kring ett dyrbart diamanthalsband?", answer: "Halsbandsaffären", accept: ["halsbandsaffären"], explanation: "Drottningen var oskyldig men skandalen skadade hennes rykte.", sources: ["sv:Halsbandsaffären"] },
    { id:"p3h-762", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vem spelade Marie Antoinette i Sofia Coppolas film från 2006?", answer: "Kirsten Dunst", accept: ["kirsten dunst","dunst"], explanation: "Filmen spelades in i Versailles.", sources: ["sv:Marie Antoinette (film)"] },
    { id:"p3h-763", category: "historia", difficulty: "svår", tags: ["p3-historia"], question: "Vad heter det lilla slottet i Versailles park som Marie Antoinette använde som tillflyktsort?", answer: "Petit Trianon", accept: ["petit trianon"], explanation: "Där lät hon bygga en låtsasbondby.", sources: ["sv:Petit Trianon"] },
    { id:"p3h-764", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken furste ledde mordet på Rasputin 1916?", answer: "Felix Jusupov", accept: ["felix jusupov","jusupov","yusupov"], explanation: "Mordet skedde i Jusupovpalatset i S:t Petersburg.", sources: ["sv:Grigorij Rasputin"] },
    { id:"p3h-765", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilket gift försökte Rasputins mördare först döda honom med?", answer: "Cyankalium", accept: ["cyankalium","cyanid"], explanation: "Han sköts sedan och kastades i en flod.", sources: ["sv:Grigorij Rasputin"] },
    { id:"p3h-766", category: "historia", difficulty: "medel", tags: ["p3-historia"], question: "Vilken sjukdom hos tronföljaren Aleksej sades Rasputin kunna lindra?", answer: "Blödarsjuka", accept: ["blödarsjuka","hemofili"], explanation: "Det gav honom stort inflytande över tsarinnan.", sources: ["sv:Grigorij Rasputin"] }
